public double trimMean(int[] arr) {
    // Calculate the mean of the array
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Calculate the 5% trimmed mean
    double trimmedMean = 0;
    int trimmedCount = (int) (arr.length * 0.05);
    for (int i = trimmedCount; i < arr.length - trimmedCount; i++) {
        trimmedMean += arr[i];
    }
    trimmedMean /= arr.length - 2 * trimmedCount;

    // Return the trimmed mean with an error within 10^-5
    return trimmedMean;
}

