public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int squares = 0;
        int remaining = n;
        while (remaining > 0) {
            int square = i * i;
            if (square > remaining) {
                break;
            }
            squares++;
            remaining -= square;
        }
        minSquares = Math.min(minSquares, squares);
    }
    return minSquares;
}

